// TODO: full validation vs contracts/tender.schema.json (title + requirements required)
const body = ($json && $json.body) ? $json.body : $json;
const out = {
  title: body.title ?? 'Untitled tender',
  source: body.source ?? 'manual',
  raw_payload: body,
  language: body.language ?? 'en',
};
return [{ json: out }];

// TODO: replace heuristic with rules + LLM score (see plan.md 1.B)
const lead = $('Validate & Normalize').first().json;
const ex = $json.output ?? $json;
let score = 50;
const t = ((ex.title ?? '') + ' ' + (ex.sector ?? '')).toLowerCase();
const itWords = ['software', 'development', 'web', 'mobile', 'application', 'digital', 'data', 'cloud', 'system', 'plateforme', 'developpement', 'numerique'];
for (const w of itWords) if (t.includes(w)) score += 8;
if (Array.isArray(ex.requirements) && ex.requirements.length >= 3) score += 10;
score = Math.max(0, Math.min(100, score));
const row = {
  title: ex.title ?? lead.title ?? 'Untitled tender',
  source: lead.source ?? 'manual',
  raw_payload: lead.raw_payload ?? lead,
  extracted: ex,
  relevance_score: score,
  deadline: ex.deadline ?? null,
};
return [{ json: { row_json: JSON.stringify(row) } }];

const src = $json ?? {};
let leadId = '';
try { leadId = src.lead_id ?? src.id ?? ''; } catch (e) {}
const errRaw = src.error ?? src.message ?? src;
const errText = typeof errRaw === 'string' ? errRaw : (errRaw.message ?? JSON.stringify(errRaw));
return [{ json: { error_json: JSON.stringify({ lead_id: String(leadId ?? ''), error: String(errText).slice(0, 500) }) } }];

